from pathlib import Path
from html import escape
from datetime import date
import json
BASE='/carta-de-cacador-portugal-web/'
ORIGIN='https://mcyj.github.io'+BASE
OUT=Path('dist')
ARTICLES=[
('guia-exame-carta-cacador','Guia atual da Carta de Caçador em Portugal','Uma visão responsável do exame, das fontes oficiais e dos limites de uma aplicação de estudo.',[
'O exame para obtenção da Carta de Caçador é administrado pelo ICNF em Portugal continental. A informação pública consultada em 28 de setembro de 2026 indica uma prova teórica com 20 perguntas, duração de 30 minutos e aprovação com pelo menos 15 respostas corretas, equivalentes a 75%. Confirme sempre a convocatória e a página oficial antes de agir.',
'A preparação abrange procedimento, legislação cinegética, biologia e identificação de espécies, ecologia, ordenamento, meios de caça, conduta no terreno, sanidade e segurança alimentar. Conhecer uma resposta isolada não substitui compreender o cenário e decidir de forma segura.',
'A app Carta de Caçador Portugal oferece cenários originais em português e um diagnóstico opcional de 20 perguntas. O resultado é apenas uma estimativa privada de estudo. Não é exame oficial, carta, licença, seguro, formação de armas nem avaliação prática.',
'Use o estudo digital juntamente com o manual, a legislação consolidada, o calendário venatório e as orientações atuais do ICNF. Em matérias de segurança, animais e armas, procure formação presencial qualificada.' ]),
('formato-20-perguntas','Formato da prova: 20 perguntas em 30 minutos','Como treinar ritmo e precisão sem confundir simulação com certificação.',[
'A referência pública do ICNF usada neste site descreve 20 perguntas de escolha múltipla, com duas ou três hipóteses e uma resposta correta. O tempo indicado é 30 minutos. Uma simulação fiel deve respeitar esta escala sem copiar perguntas oficiais.',
'Para passar, a referência indica pelo menos 75%, ou 15 respostas certas. Como números e procedimentos podem mudar, reveja a informação oficial perto da data da prova e siga sempre a sua convocatória.',
'Num treino de 20 perguntas, faça primeiro uma passagem calma, marque as dúvidas e reserve os minutos finais para rever enunciados e negações. Não altere uma resposta apenas por ansiedade; procure uma razão concreta.',
'O simulador da app mede apenas o desempenho naquele conjunto independente. Não prevê um resultado oficial e não observa identificação de espécies no terreno, manuseamento seguro ou outra competência prática.' ]),
('inscricao-taxas-2026-2027','Inscrição e taxas ICNF 2026–2027','Valores publicados, custos separados e o que confirmar antes do pagamento.',[
'A tabela oficial consultada para o período de 1 de junho de 2026 a 31 de maio de 2027 publica 21,50 € para inscrição no exame de candidatos com menos de 25 anos e 43,00 € para candidatos acima dessa faixa, conforme a regra etária indicada pelo ICNF.',
'A emissão inicial da carta aparece separadamente, por 13,51 €. Estes valores não incluem necessariamente deslocação, formação, equipamento, seguro, licença de caça ou outros requisitos pessoais. Por isso, evite apresentar a soma como custo completo universal.',
'Antes de pagar, confirme elegibilidade, documentos, local, data, entidade recebedora e tabela vigente diretamente no ICNF. Não use links recebidos sem verificar o domínio e guarde o comprovativo oficial.',
'A subscrição da app é uma compra digital independente. Não paga inscrição, emissão, licença nem reserva de exame. Enquanto a versão iOS está em análise, este site não apresenta um botão de instalação ativo.' ]),
('plano-estudo-quatro-semanas','Plano de estudo de quatro semanas','Uma sequência equilibrada entre lei, espécies, segurança e revisão.',[
'Na primeira semana, organize as fontes: procedimento atual, lei consolidada, calendário e manual. Estude conceitos como terreno cinegético, área de proteção, período venatório e diferença entre carta e licença.',
'Na segunda semana, trabalhe identificação e biologia. Compare espécies semelhantes, habitat, comportamento e sinais. A regra de campo é simples: se a identificação ou o fundo não forem seguros, não existe disparo.',
'Na terceira semana, concentre-se em segurança, meios, cães, cetraria, biossegurança e recuperação responsável. Conteúdo digital ajuda na teoria, mas não substitui instrução presencial nem prática supervisionada.',
'Na última semana, alterne simulados de 20 perguntas com revisão dos erros. Registe a razão de cada erro, volte à fonte oficial e faça pelo menos uma sessão no ritmo de 30 minutos sem interrupções.' ]),
('estudar-legislacao-cinegetica','Como estudar legislação cinegética sem decorar frases','Método por conceitos, decisões e revalidação das regras atuais.',[
'Comece pelas definições que estruturam as decisões: recurso cinegético, ato venatório, terreno cinegético, terreno não cinegético, área de proteção, refúgio e jornada. Relacione cada conceito com uma situação concreta.',
'Depois separe regras estáveis de dados variáveis. Princípios de segurança e conservação tendem a ser duradouros; espécies autorizadas, períodos, taxas, editais e condicionamentos exigem confirmação atual.',
'Crie cartões com uma pergunta de decisão: “que informação falta?” ou “o que bloqueia a ação?”. Esse formato evita memorização cega e treina a resposta conservadora perante incerteza.',
'Nunca use a app como texto legal. Consulte o Diário da República e o ICNF. Quando duas fontes parecerem divergir, suspenda a conclusão e procure a redação consolidada ou orientação competente.' ]),
('identificacao-especies','Identificação de espécies: estudar para evitar o erro','Como combinar morfologia, habitat e comportamento com uma decisão segura.',[
'Uma identificação responsável usa vários sinais: forma, dimensão, plumagem ou pelagem, movimento, vocalização, habitat, época e composição do grupo. Um único vestígio ou uma silhueta rápida raramente basta.',
'Estude também espécies não cinegéticas e protegidas que podem ser confundidas. Reconhecer o que não pode ser alvo é tão importante como conhecer a espécie pretendida.',
'Use imagens atuais e fontes de conservação, mas trate fotografias como preparação. Luz, distância e cobertura vegetal mudam a perceção no terreno. A dúvida deve sempre terminar em não disparar.',
'As perguntas independentes da app trabalham decisões e sinais conceituais. Não reproduzem o questionário oficial e não avaliam a identificação prática em condições reais.' ]),
('seguranca-campo-armas','Segurança no campo e com armas','Princípios que devem permanecer acima da pontuação e da oportunidade.',[
'Mantenha o cano numa direção segura e o dedo fora do gatilho até existir decisão deliberada de disparar. Identifique alvo, trajetória e fundo. Movimento, som ou cor isolados não são um alvo.',
'Descarregue antes de atravessar obstáculos, entrar em veículos ou lidar com uma queda. Se houver falha de fogo ou possível obstrução, mantenha direção segura e siga o manual e a formação recebida.',
'Num grupo, defina postos, setores, sinais e procedimento de paragem. Nevoeiro, pessoas, estradas, animais domésticos ou perda de comunicação podem obrigar a suspender a atividade.',
'Esta página não ensina operação de uma arma. Procure instrução prática qualificada e cumpra a legislação, licenciamento, armazenamento, transporte e regras do local.' ]),
('usar-simulados','Como usar simulados sem criar falsa confiança','Transforme cada tentativa num ciclo de diagnóstico, fonte e nova decisão.',[
'Faça o primeiro diagnóstico sem estudar para obter um ponto de partida. O resultado serve para priorizar capítulos e não representa probabilidade oficial de aprovação.',
'Em cada erro, classifique a causa: desconhecimento, leitura apressada, regra desatualizada ou confusão entre espécies e contextos. Volte à fonte apropriada e escreva a razão da resposta correta.',
'Varie a ordem dos temas e faça sessões cronometradas só depois de compreender os conceitos. Repetir a mesma sequência pode medir memória do ecrã em vez de aprendizagem.',
'Na app, o diagnóstico pode ser ignorado por quem começa do zero. Depois do resultado, o conteúdo de estudo exige Premium ou entitlement verificado; Restore Purchases permanece disponível para subscritores existentes.' ]),
('checklist-dia-exame','Checklist para o dia do exame','Confirmações administrativas e uma rotina simples para reduzir imprevistos.',[
'Na véspera, confirme local, hora, identificação, convocatória, documentos e instruções atuais. Planeie deslocação com margem e não dependa de uma captura de ecrã desatualizada.',
'Leve apenas materiais permitidos. A app não deve ser usada durante uma sessão controlada se as regras não o permitirem. Siga as instruções do responsável e esclareça dúvidas antes do início.',
'Leia cada pergunta por completo, repare em palavras como “não”, “sempre” e “apenas” e controle o tempo. Com 30 minutos para 20 perguntas, existe margem para uma revisão final sem pressa.',
'Depois da prova, use apenas o canal oficial para resultado e próximos passos. Uma pontuação do treino não antecipa nem altera o registo oficial.' ]),
('revisao-erros-e-repeticao','Revisão de erros e nova tentativa','Como recuperar lacunas sem memorizar a posição das opções.',[
'Guarde o tema e a explicação do erro, não apenas a letra escolhida. Formule uma nova situação em que o mesmo princípio seja aplicado de outra forma.',
'Se o erro envolve valor, prazo, espécie autorizada ou período venatório, confirme se a fonte continua vigente. Informação antiga pode produzir uma resposta coerente e ainda assim errada hoje.',
'Intercale revisão espaçada com testes mistos. Um bom sinal de domínio é explicar por que cada opção insegura ou incompatível deve ser rejeitada.',
'Para uma repetição oficial, consulte as condições atuais do ICNF e a sua notificação. Este site não fixa prazo de repetição nem promete elegibilidade, porque esses dados dependem do processo vigente.' ])]

def nav(prefix=''):
 return f'''<header class="top"><a class="brand" href="{BASE}"><img src="{BASE}assets/app-icon.png" alt="Ícone Carta de Caçador Portugal"><span>Carta de Caçador Portugal</span></a><nav aria-label="Navegação principal"><a href="{BASE}#funcionalidades">App</a><a href="{BASE}guias/">Guias</a><a href="{BASE}suporte/">Suporte</a><a href="{BASE}en/" lang="en">EN</a></nav></header>'''

def head(title,desc,path='',lang='pt-PT',hreflang=False):
 url=ORIGIN+path
 alt=(f'<link rel="alternate" hreflang="pt-PT" href="{ORIGIN}"><link rel="alternate" hreflang="en" href="{ORIGIN}en/"><link rel="alternate" hreflang="x-default" href="{ORIGIN}">' if hreflang else '')
 return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc)}"><link rel="canonical" href="{url}">{alt}<meta property="og:type" content="website"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{ORIGIN}assets/app-icon.png"><link rel="icon" href="{BASE}assets/app-icon.png"><link rel="stylesheet" href="{BASE}assets/style.css"></head><body><a class="skip" href="#conteudo">Saltar para o conteúdo</a>{nav()}'''

def foot():
 return f'''<footer><p><strong>Preparação independente.</strong> Sem afiliação ou aval do ICNF.</p><nav aria-label="Informação legal"><a href="{BASE}privacidade/">Privacidade</a><a href="{BASE}termos/">Termos</a><a href="{BASE}suporte/">Suporte</a><a href="{BASE}contacto/">Contacto</a></nav><p>Informação verificada em 28-09-2026. Confirme sempre no <a href="https://www.icnf.pt/caca/cacar/exame/procedimentosdeexame">ICNF</a>.</p></footer></body></html>'''

def write(path,html):
 p=OUT/path;p.mkdir(parents=True,exist_ok=True);(p/'index.html').write_text(html)

def cards():
 return ''.join(f'<article class="card"><p class="eyebrow">Guia</p><h3><a href="{BASE}guias/{slug}/">{escape(title)}</a></h3><p>{escape(desc)}</p></article>' for slug,title,desc,_ in ARTICLES)

def build():
 if OUT.exists():
  import shutil;shutil.rmtree(OUT)
 (OUT/'assets').mkdir(parents=True)
 import shutil;shutil.copy('assets/app-icon.png',OUT/'assets/app-icon.png');shutil.copy('assets/style.css',OUT/'assets/style.css')
 desc='Preparação independente em português para o Exame da Carta de Caçador: diagnóstico, cenários originais e simulador de 20 perguntas.'
 structured='''<script type="application/ld+json">{"@context":"https://schema.org","@type":"SoftwareApplication","name":"Carta de Caçador Portugal","applicationCategory":"EducationalApplication","operatingSystem":"iOS, Android","description":"Preparação independente para o exame da Carta de Caçador em Portugal.","offers":{"@type":"Offer","availability":"https://schema.org/PreOrder"}}</script>'''
 home=head('Carta de Caçador Portugal — preparação independente',desc,'','pt-PT',True)+structured+f'''<main id="conteudo"><section class="hero"><div><p class="eyebrow">PREPARAÇÃO INDEPENDENTE · PORTUGAL</p><h1>Estude decisões seguras, não respostas decoradas.</h1><p class="lead">Cenários originais em português, diagnóstico opcional de 20 perguntas e revisão local para organizar a preparação da Carta de Caçador.</p><div class="actions"><span class="button disabled" aria-label="Aplicação iOS em análise, indisponível para instalação">App Store · Em análise</span><a class="button secondary" href="https://www.icnf.pt/caca/cacar/exame/procedimentosdeexame">Consultar o ICNF</a></div><p class="status">A versão iOS 0.1.1 está em <strong>WAITING_FOR_REVIEW</strong>. Não apresentamos um link de instalação antes da publicação.</p></div><img class="hero-icon" src="{BASE}assets/app-icon.png" width="1024" height="1024" alt="Ícone verde da aplicação Carta de Caçador Portugal"></section>
<section class="facts" aria-label="Estrutura pública consultada"><div><strong>20</strong><span>perguntas</span></div><div><strong>30 min</strong><span>duração indicada</span></div><div><strong>15/20</strong><span>referência de aprovação</span></div><div><strong>120</strong><span>cenários v2 originais</span></div></section>
<section id="funcionalidades"><p class="eyebrow">FLUXO DE ESTUDO</p><h2>Diagnóstico, resultado privado e estudo Premium</h2><div class="grid3"><article><h3>Começar ou ignorar</h3><p>Faça cerca de 20 perguntas para conhecer o ponto de partida, ou ignore se começa do zero.</p></article><article><h3>Resultado não oficial</h3><p>A estimativa fica no dispositivo e não garante aprovação, elegibilidade ou licença.</p></article><article><h3>Entitlement preservado</h3><p>Subscritores verificados mantêm acesso; compras existentes podem usar Restore Purchases.</p></article></div></section>
<section><p class="eyebrow">FONTES E LIMITES</p><h2>Preparação alinhada com fontes públicas</h2><p class="wide">O conteúdo usa o âmbito público do ICNF e legislação consolidada como referência temática, sem copiar o questionário oficial. A aplicação não substitui formação prática, segurança de armas, identificação no terreno, seguro, inscrição, licença ou carta.</p></section>
<section><div class="section-head"><div><p class="eyebrow">GUIAS</p><h2>Informação para preparar com responsabilidade</h2></div><a href="{BASE}guias/">Ver todos</a></div><div class="cards">{cards()}</div></section></main>'''+foot()
 write(Path('.'),home)
 guides=head('Guias da Carta de Caçador','Guias independentes sobre formato, inscrição, estudo, espécies e segurança.','guias/')+f'<main id="conteudo"><p class="eyebrow">CENTRO DE GUIAS</p><h1>Preparar com fontes, contexto e segurança</h1><p class="lead">Dez guias originais. Dados variáveis devem ser confirmados diretamente no ICNF.</p><div class="cards">{cards()}</div></main>'+foot();write(Path('guias'),guides)
 for slug,title,ad,paras in ARTICLES:
  body=''.join(f'<p>{escape(p)}</p>' for p in paras)
  article_data={"@context":"https://schema.org","@type":"Article","headline":title,"datePublished":"2026-09-28","dateModified":"2026-09-28","author":{"@type":"Organization","name":"RushLabs"},"mainEntityOfPage":ORIGIN+f'guias/{slug}/'}
  ld=f'<script type="application/ld+json">{json.dumps(article_data, ensure_ascii=False, separators=(",", ":"))}</script>'
  html=head(title+' — Carta de Caçador Portugal',ad,f'guias/{slug}/')+ld+f'<main id="conteudo" class="article"><nav class="crumb" aria-label="Breadcrumb"><a href="{BASE}">Início</a> / <a href="{BASE}guias/">Guias</a></nav><p class="eyebrow">GUIA · ATUALIZADO 28-09-2026</p><h1>{escape(title)}</h1><p class="lead">{escape(ad)}</p>{body}<aside><strong>Confirmação oficial</strong><p>Consulte procedimento, convocatória e legislação atuais antes de tomar qualquer decisão.</p><a href="https://www.icnf.pt/caca/cacar/exame/procedimentosdeexame">Abrir o ICNF</a></aside><p><a class="button secondary" href="{BASE}guias/">Voltar aos guias</a></p></main>'+foot();write(Path('guias')/slug,html)
 privacy=head('Privacidade — Carta de Caçador Portugal','Como o site e a aplicação tratam informação.','privacidade/')+f'''<main id="conteudo" class="article"><h1>Privacidade</h1><p>Este site estático não inclui analytics, formulários, contas ou cookies de publicidade nesta versão. O alojamento GitHub Pages pode manter registos técnicos segundo as políticas do GitHub.</p><p>A aplicação foi concebida com progresso de estudo local. Compras e restauros usam as interfaces das lojas. Não envie dados pessoais, documentos de caça, detalhes de armas ou informação clínica por email de suporte.</p><p>Se funcionalidades futuras alterarem a recolha de dados, esta política deverá ser atualizada antes da publicação.</p><p>Contacto: <a href="mailto:june1012june@gmail.com">june1012june@gmail.com</a>.</p></main>'''+foot();write(Path('privacidade'),privacy)
 terms=head('Termos — Carta de Caçador Portugal','Limites do serviço independente de estudo.','termos/')+'''<main id="conteudo" class="article"><h1>Termos de utilização</h1><p>O conteúdo é preparação independente e não está afiliado nem é avalizado pelo ICNF. Não constitui aconselhamento jurídico, formação de armas, certificação, seguro, inscrição, licença ou Carta de Caçador.</p><p>Não existe garantia de aprovação. Regras, taxas e calendários podem mudar; o utilizador deve confirmar fontes oficiais. As compras digitais seguem os termos e mecanismos de restituição da respetiva loja.</p><p>É proibido usar o conteúdo para substituir supervisão prática, contornar regras de segurança ou justificar atividade não autorizada.</p></main>'''+foot();write(Path('termos'),terms)
 support=head('Suporte — Carta de Caçador Portugal','Ajuda com acesso, diagnóstico e restauro de compra.','suporte/')+f'''<main id="conteudo" class="article"><h1>Suporte</h1><h2>Restaurar uma compra</h2><p>Abra o paywall e escolha Restore Purchases com a mesma conta da loja usada na compra. Uma nova instalação sem entitlement verificado permanece bloqueada.</p><h2>Resultado do diagnóstico</h2><p>O resultado é uma estimativa privada e não oficial. Pode ignorar o diagnóstico se começa do zero.</p><h2>Questões sobre exame ou licença</h2><p>Contacte o ICNF. O suporte da app não confirma elegibilidade, documentos, armas, licenças ou calendário.</p><h2>Contacto técnico</h2><p><a href="mailto:june1012june@gmail.com">june1012june@gmail.com</a>. Indique versão, dispositivo e passos para reproduzir; não envie documentos pessoais.</p></main>'''+foot();write(Path('suporte'),support)
 contact=head('Contacto — Carta de Caçador Portugal','Contacto técnico da aplicação independente.','contacto/')+'''<main id="conteudo" class="article"><h1>Contacto</h1><p>Suporte técnico RushLabs: <a href="mailto:june1012june@gmail.com">june1012june@gmail.com</a>.</p><p>Para inscrição, exame, carta, licença, legislação ou calendário, use os contactos oficiais do ICNF.</p></main>'''+foot();write(Path('contacto'),contact)
 en=head('Carta de Caçador Portugal — independent study app','Independent Portuguese hunting-licence theory study with an optional diagnostic and original scenarios.','en/','en',True)+f'''<main id="conteudo"><section class="hero"><div><p class="eyebrow">INDEPENDENT STUDY · PORTUGAL</p><h1>Prepare with safety-first decisions.</h1><p class="lead">Original Portuguese scenarios, an optional 20-question diagnostic and local progress. Not affiliated with ICNF and not a licence, official exam or practical training.</p><div class="actions"><span class="button disabled">App Store · Under review</span><a class="button secondary" href="https://www.icnf.pt/caca/cacar/exame/procedimentosdeexame">Official ICNF information</a></div><p class="status">iOS version 0.1.1 is currently WAITING_FOR_REVIEW. No install link is shown before publication.</p></div><img class="hero-icon" src="{BASE}assets/app-icon.png" alt="Carta de Caçador Portugal app icon"></section><section><h2>Verified public reference</h2><p class="wide">The consulted public structure is 20 questions, 30 minutes and 15 correct answers. Reconfirm current eligibility, dates, documents and rules with ICNF.</p></section></main>'''+foot();write(Path('en'),en)
 notfound=head('Página não encontrada','A página solicitada não existe.','404.html')+f'<main id="conteudo" class="article"><h1>Página não encontrada</h1><p><a href="{BASE}">Voltar ao início</a></p></main>'+foot();(OUT/'404.html').write_text(notfound)
 urls=[ORIGIN,ORIGIN+'guias/',ORIGIN+'privacidade/',ORIGIN+'termos/',ORIGIN+'suporte/',ORIGIN+'contacto/',ORIGIN+'en/']+[ORIGIN+'guias/'+a[0]+'/' for a in ARTICLES]
 (OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{u}</loc><lastmod>2026-09-28</lastmod></url>' for u in urls)+'</urlset>')
 (OUT/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: {ORIGIN}sitemap.xml\n')
 (OUT/'.nojekyll').write_text('')

if __name__=='__main__': build(); print(f'built {sum(1 for _ in OUT.rglob("*.html"))} html pages')
